function shopKey(card){
 if(card.classList.contains('card-all'))return 'all';
 if(card.classList.contains('card-markets'))return 'markets';
 if(card.classList.contains('card-library'))return 'library';
 if(card.classList.contains('card-mobiles'))return 'mobiles';
 if(card.classList.contains('card-electronics'))return 'electronics';
 const href=card.getAttribute('href')||'';
 if(href.includes('section=printers'))return 'printers';
 if(href.includes('shop-store-suggestion.html'))return 'suggest-store';
 if(card.id==='superAdminAddStoreBox'||card.classList.contains('ha-add-store-card')||href.includes('seller-registration.html'))return 'add-store';
 return '';
}
function mount(root){
 const page=(location.pathname.split('/').pop()||'index.html').toLowerCase();
 const config=artwork.pages[page];
 if(config){
  root.querySelectorAll?.('.ha-section-cover,.ha-shop-premium-hero').forEach(cover=>{
   let img=cover.querySelector('img');
   if(!img||img.dataset.haCleanArtwork)return;
   if(!img.dataset.haDefaultSrc)img.src=artwork.covers[config.key];
   img.dataset.haCleanArtwork=config.key;
  });
 }
 root.querySelectorAll?.('.ha-shop-premium-cats > a.ha-cat').forEach(card=>{
  if(card.dataset.haCleanShop)return;
  const key=shopKey(card);if(!key||!artwork.shop[key])return;
  card.dataset.haCleanShop=key;
  if(!card.dataset.haCardLabel){
   const label=card.getAttribute('aria-label')||card.querySelector('strong')?.textContent||'';
   if(label)card.dataset.haCardLabel=label.replace(/\s+/g,' ').trim();
  }
  card.style.setProperty('background-image','url("'+artwork.shop[key]+'")','important');
 });
}
artwork.mount=mount;
window.HASectionArtwork=artwork;
